Here is the plain C kernel:
```cpp
#include "fdtd-2d.h"


void kernel_fdtd_2d(


		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{


    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

  int t, i, j;


  for(t = 0; t < tmax; t++)
    {
      for (j = 0; j < ny; j++)
	ey[0][j] = _fict_[t];
      for (i = 1; i < nx; i++)
	for (j = 0; j < ny; j++)
	  ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
      for (i = 0; i < nx; i++)
	for (j = 1; j < ny; j++)
	  ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
      for (i = 0; i < nx - 1; i++)
	for (j = 0; j < ny - 1; j++)
	  hz[i][j] = hz[i][j] - 0.7*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
    }

}
```

Provide the complete HLS-optimized code in a ```cpp code fence.

```cpp
#include "fdtd-2d.h"

extern "C" {

void kernel_fdtd_2d(
		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex     offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey     offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz     offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3

#pragma HLS INTERFACE s_axilite port=ex      bundle=control
#pragma HLS INTERFACE s_axilite port=ey      bundle=control
#pragma HLS INTERFACE s_axilite port=hz      bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int tmax = TMAX;
    const int nx   = NX;
    const int ny   = NY;

    // Local copies to avoid repeated global memory accesses
    double l_ex   [NX][NY];
    double l_ey   [NX][NY];
    double l_hz   [NX][NY];
    double l_fict [TMAX];

#pragma HLS ARRAY_PARTITION variable=l_ex    cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_ey    cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_hz    cyclic factor=8 dim=2

    // Load _fict_
    for (int t = 0; t < tmax; t++) {
#pragma HLS PIPELINE II=1
        l_fict[t] = _fict_[t];
    }

    // Load ex, ey, hz
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ex[i][j] = ex[i][j];
            l_ey[i][j] = ey[i][j];
            l_hz[i][j] = hz[i][j];
        }
    }

    // Main computation
    int t, i, j;

    for (t = 0; t < tmax; t++) {

        // ey[0][j] = _fict_[t]
        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ey[0][j] = l_fict[t];
        }

        // ey[i][j] update (i >= 1)
        for (i = 1; i < nx; i++) {
            for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ey[i][j] = l_ey[i][j] - 0.5 * (l_hz[i][j] - l_hz[i-1][j]);
            }
        }

        // ex[i][j] update (j >= 1)
        for (i = 0; i < nx; i++) {
            for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ex[i][j] = l_ex[i][j] - 0.5 * (l_hz[i][j] - l_hz[i][j-1]);
            }
        }

        // hz[i][j] update
        for (i = 0; i < nx - 1; i++) {
            for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
                l_hz[i][j] = l_hz[i][j] - 0.7 * (l_ex[i][j+1] - l_ex[i][j] +
                                                    l_ey[i+1][j] - l_ey[i][j]);
            }
        }
    }

    // Write back ex, ey, hz
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            ex[i][j] = l_ex[i][j];
            ey[i][j] = l_ey[i][j];
            hz[i][j] = l_hz[i][j];
        }
    }
}

} // extern "C"
```
